(function(root,factory){const common=typeof module==='object'&&module.exports;const api=factory(common?require('./engine.js'):root.TravellerEngine,common?require('./english.js'):root.TravellerEnglish);if(common)module.exports=api;else root.TravellerEquipmentUI=api})(globalThis,function(E,L){
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>'Cr'+Number(n||0).toLocaleString('en-GB');
function funds(s){if(s.finalFunds)return {cash:s.finalFunds.cash,debt:s.finalFunds.debt,settled:true};const gross=(s.careerHistory||[]).reduce((n,c)=>n+(c.benefits?.cash||0),0)+(s.activeCareer?s.benefits?.cash||0:0),cost=s.medicalDue+s.anagathics.cost+s.psiCost;return {cash:Math.max(0,gross-cost),debt:Math.max(0,cost-gross),settled:false}}
function inventory(s){return [...(s.assets||[]).map(name=>({name:L.english(name),quantity:1,source:'Career Benefit / Event'})),...(s.equipment?.purchases||[])]}
function panel(s){const f=funds(s),list=inventory(s);return `<section class="possessions" data-key="possessions"><div class="finance-line"><span>Age <b>${s.age}</b></span><span>${f.settled?'Credits':'Credits after costs'} <b>${cash(f.cash)}</b></span><span>Debt <b>${cash(f.debt)}</b></span><span>Ship Shares <b>${s.shares||0}</b></span></div><div class="inventory-heading">Inventory</div><ul class="inventory-list">${list.length?list.map(x=>`<li>${esc(x.name)}${x.quantity>1?' ×'+x.quantity:''} <small>${x.source==='purchase'?'Purchased':esc(x.source)}</small></li>`).join(''):'<li class="muted">No items acquired.</li>'}</ul></section>`}
function shop(s,filter={}){const q=E.EQUIPMENT,e=s.equipment||{cart:[],spent:0},cost=q.total(e.cart),limit=Math.max(0,Math.min(q.LIMIT-e.spent,s.finalFunds.cash));return `<p class="eyebrow">Finishing Touches</p><h1>Starting equipment.</h1><p>Outstanding costs have been settled. Spend up to Cr2,000 on personal equipment; career Benefits are already yours. More expensive purchases take place during play.</p><p class="equipment-budget">Available <strong>${cash(limit)}</strong> · Selected <strong>${cash(cost)}</strong> · Remaining <strong>${cash(limit-cost)}</strong></p><p class="note">Personal equipment from Core Rules pp. 87–103: armour, weapons, ammunition, communications, computers, software, medical supplies, tools and survival gear. TL is shown for reference; local availability is agreed with the Referee.</p><div class="equipment-tools"><input data-equipment-search placeholder="Find equipment…" aria-label="Find equipment" value="${esc(filter.query||'')}"><select data-equipment-category aria-label="Equipment category"><option value="">All categories</option>${[...new Set(q.items.map(x=>x.category))].map(c=>`<option value="${esc(c)}" ${filter.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="equipment-catalogue">${q.items.map(x=>{const quantity=e.cart.find(c=>c.id===x.id)?.quantity||0;return `<div class="equipment-row" data-key="equipment-${x.id}" data-item-name="${esc(x.name.toLowerCase())}" data-item-category="${esc(x.category)}" ${filter.query&&!x.name.toLowerCase().includes(filter.query.toLowerCase())||filter.category&&filter.category!==x.category?'hidden':''}><div><strong>${esc(x.name)}</strong><small>${x.category} · ${x.tl?'TL '+x.tl:'TL —'} · ${x.mass?x.mass+' kg':'Negligible mass'} · ${cash(x.cost)}</small></div><div class="equipment-quantity"><button type="button" data-command="equipment-remove" data-value="${x.id}" data-revision="${s.revision}" aria-label="Remove ${esc(x.name)}" ${!quantity?'disabled':''}>−</button><span>${quantity}</span><button type="button" data-command="equipment-add" data-value="${x.id}" data-revision="${s.revision}" aria-label="Add ${esc(x.name)}">+</button></div></div>`}).join('')}</div><p class="note">${cost>limit?'Selection exceeds the available budget. Remove items before continuing.':'You may keep your remaining credits and finish without buying anything.'}</p>`}
return {funds,inventory,panel,shop};
});
